#include <omp.h>
#include <vector>
#include <array>

struct Point {
   double x, y;
};

/* Count the number of cartesian points in each quadrant. The vector points contains a list of `Point` objects.
   Store the counts in `bins`.
   Use OpenMP to count in parallel.
   Example:

   input: [{x=1.5, y=0.1}, {x=-3, y=1.1}, {x=5, y=9}, {x=1.5, y=-1}, {x=3, y=-7}, {x=0.1, y=2}]
   output: [3, 1, 0, 2]
*/
void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    // Initialize bins to zero
    bins[0] = 0; // Quadrant I: x > 0, y > 0
    bins[1] = 0; // Quadrant II: x < 0, y > 0
    bins[2] = 0; // Quadrant III: x < 0, y < 0
    bins[3] = 0; // Quadrant IV: x > 0, y < 0

    // Use private accumulators per thread to avoid race conditions
    #pragma omp parallel
    {
        std::array<size_t, 4> local_bins = {0, 0, 0, 0};

        #pragma omp for nowait
        for (size_t i = 0; i < points.size(); ++i) {
            double x = points[i].x;
            double y = points[i].y;

            if (x > 0 && y > 0) {
                local_bins[0]++;
            } else if (x < 0 && y > 0) {
                local_bins[1]++;
            } else if (x < 0 && y < 0) {
                local_bins[2]++;
            } else if (x > 0 && y < 0) {
                local_bins[3]++;
            }
            // Points on axes (x==0 or y==0) are not counted in any quadrant
        }

        // Reduce local_bins into global bins
        #pragma omp critical
        {
            bins[0] += local_bins[0];
            bins[1] += local_bins[1];
            bins[2] += local_bins[2];
            bins[3] += local_bins[3];
        }
    }
}
